  return join(resolveCanonicalRuntimeProjectRoot(root), '.lattice', 'runtime', 'host-runs');
}

export function managedHostRunReceiptsRoot(root: string): string {
  return join(resolveCanonicalRuntimeProjectRoot(root), '.lattice', 'runtime', 'host-run-receipts');
