async function reconcileManagedHostRunUnlocked(
  paths: ManagedHostRunPaths,
  now: number,
  processGroupOps: ManagedHostRunProcessGroupOps = DEFAULT_PROCESS_GROUP_OPS,
): Promise<void> {
