const HOST_RUN_PROCESS_GROUP_TERM_GRACE_MS = 250;
const HOST_RUN_PROCESS_GROUP_KILL_GRACE_MS = 250;

function processStartFingerprint(pid: number): string | null {
  if (process.platform === 'win32' || !Number.isSafeInteger(pid) || pid <= 0) return null;
  try {
    const value = execFileSync('ps', ['-o', 'lstart=', '-p', String(pid)], {
      encoding: 'utf8',
      timeout: 1_000,
      stdio: ['ignore', 'pipe', 'ignore'],
    }).trim();
    return value.length > 0 ? value : null;
  } catch {
    return null;
  }
}

function isolatedProcessGroupAlive(pgid: number | null): boolean {
  if (process.platform === 'win32' || !pgid || pgid <= 1) return false;
  try {
    process.kill(-pgid, 0);
    return true;
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === 'EPERM';
  }
}

function isolatedProcessGroupIsLeaderless(identity: HostRunProcessIdentity): boolean {
  if (process.platform === 'win32' || !isSafeIsolatedProviderProcessGroup(identity)) return false;
  try {
    const rows = execFileSync('ps', ['-axo', 'pid=,pgid='], {
      encoding: 'utf8',
      timeout: 1_000,
      stdio: ['ignore', 'pipe', 'ignore'],
    })
      .split('\n')
      .map(line => /^\s*(\d+)\s+(\d+)\s*$/.exec(line))
      .filter((row): row is RegExpExecArray => row !== null)
      .map(row => ({ pid: Number(row[1]), pgid: Number(row[2]) }))
      .filter(row => row.pgid === identity.pgid);
    // A nonempty group whose original leader PID is absent has not been
    // recycled: POSIX cannot reuse its PGID until its last member exits.
    return rows.length > 0 && !rows.some(row => row.pid === identity.pid);
  } catch {
    return false;
  }
}

function signalIsolatedProcessGroup(
  identity: HostRunProcessIdentity | null,
  signal: NodeJS.Signals,
  readStartFingerprint: (pid: number) => string | null,
  send: (pgid: number, signal: NodeJS.Signals) => boolean,
): boolean {
  if (!isSafeIsolatedProviderProcessGroup(identity)) return false;
  // A stale PID/PGID must never be signalled. This exact revalidation mirrors
  // managed reconciliation: the detached group leader is authority only while
  // its observed start fingerprint still names the spawned leader.
  if (readStartFingerprint(identity.pid) !== identity.startFingerprint) return false;
  return send(identity.pgid, signal);
}

function signalVerifiedOrLeaderlessProcessGroup(
  identity: HostRunProcessIdentity | null,
  signal: NodeJS.Signals,
  readStartFingerprint: (pid: number) => string | null,
  isLeaderless: (identity: HostRunProcessIdentity) => boolean,
  send: (pgid: number, signal: NodeJS.Signals) => boolean,
): boolean {
  if (!isSafeIsolatedProviderProcessGroup(identity)) return false;
  if (readStartFingerprint(identity.pid) === identity.startFingerprint) return send(identity.pgid, signal);
  // The only safe exception to live-leader revalidation is a directly observed
  // leaderless group. It contains descendants of this exact still-live PGID,
  // so no PGID reuse could have occurred; an unreadable/mismatched leader is
  // never treated as this exception.
  return isLeaderless(identity) ? send(identity.pgid, signal) : false;
}

function signalProcessGroup(pgid: number, signal: NodeJS.Signals): boolean {
  if (process.platform === 'win32' || pgid <= 1) return false;
  try {
    process.kill(-pgid, signal);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ESRCH') return true;
    return false;
  }
}

